var assert = globalThis.assert;

var cz = loadModule('js/common/checkRunZombies.js', makeRequire({}), {});

var NOW = Date.parse('2026-10-10T15:00:00Z');
var RUN_GREEN = '38057801418';          // the 13:58 green run (fa #1457)
