        assert.equal(wide.zombies.length, 0, 'inside a 15-min grace ⇒ live');
        var narrow = cz.classify([cr()], resolver(map, {}), NOW, { runConcludedGraceMinutes: 5 });
        assert.equal(narrow.zombies.length, 1, 'past a 5-min grace ⇒ zombie');
