    // tick; stale runs are cancelled by validate_pr (agents#519).
    var cfg = JSON.parse(file_read({ path: 'sm_github.json' }));
    var rules = (function dig(o) {
        if (o && typeof o === 'object') {
            if (Array.isArray(o.rules)) return o.rules;
