        var queued = cz.classify([cr({ details_url: 'https://github.com/o/r/actions/runs/' + RUN_LIVE })],
                                 resolver(map, {}), NOW, {});
        assert.equal(queued.zombies.length, 0, 'a queued (waiting-for-runner) run is LIVE');
