function zombieWindowMsOf(jobParams) {
    var n = (jobParams || {}).zombieRedispatchMinMs;
    n = typeof n === 'string' ? parseInt(n, 10) : n;
    if (typeof n !== 'number' || isNaN(n) || n < 0) return 60 * 60 * 1000;
