        var stamp = cr({ details_url: null, started_at: '2026-10-10T14:55:00Z' });
        var out = cz.classify([stamp], resolver({}, {}), NOW, {});
        assert.equal(out.zombies.length, 0);
        assert.equal(out.live, 1);
    });

