        while ((m = PLACEHOLDER_MARKER_RE.exec(s)) !== null) {
            var atMs = Date.parse(m[3]);
            if (isNaN(atMs)) continue;
            if (now - atMs < 0 || now - atMs >= win) continue;   // outside the trailing window
            count++;
            if (lastAtMs === null || atMs > lastAtMs) lastAtMs = atMs;
        }
    });
