function placeholderMarks(bodies, nowMs, windowMs) {
    // Per-PR windowed count (NOT per head — every reset mints a NEW head,
    // so head-keyed counting would never reach a cap). Only markers whose
    // timestamp sits inside the trailing window count; the cap is
    // "N resets per PR per window".
    var now = typeof nowMs === 'number' ? nowMs : Date.now();
    var win = typeof windowMs === 'number' && windowMs > 0 ? windowMs : DEFAULT_PLACEHOLDER_RESET_WINDOW_MS;
    var count = 0, lastAtMs = null;
    (bodies || []).forEach(function (body) {
