    n = typeof n === 'string' ? parseInt(n, 10) : n;
    if (typeof n !== 'number' || isNaN(n) || n < 0) return DEFAULT_PLACEHOLDER_RESET_WINDOW_MS;
    return Math.floor(n);
}
