    n = typeof n === 'string' ? parseInt(n, 10) : n;
    return (typeof n === 'number' && n > 0) ? Math.floor(n) : DEFAULT_PLACEHOLDER_RESET_CAP;
}

function placeholderWindowMsOf(jobParams) {
